// Collect sanitized execution metadata (no item data) for a failed execution.
const { executionId } = $input.first().json;
const r = await this.helpers.httpRequest({
  method: 'GET', url: `http://127.0.0.1:5678/api/v1/executions/${encodeURIComponent(executionId)}?includeData=false`,
  headers: { 'X-N8N-API-KEY': $env.N8N_PUBLIC_API_KEY }, json: true, timeout: 10000,
});
const started = r.startedAt ? new Date(r.startedAt).getTime() : null;
const stopped = r.stoppedAt ? new Date(r.stoppedAt).getTime() : null;
return [{ json: { executionId, mode: r.mode, status: r.status, retryOf: r.retryOf ?? null, startedAt: r.startedAt, durationMs: started && stopped ? stopped - started : null } }];
